solution_code:
function sumPositive(numbers) {
    return numbers
        .filter(number => number > 0)
        .reduce((total, number) => total + number, 0);
}

function titleCase(text) {
    return text
        .split(" ")
        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(" ");
}

